#pragma once

#include <juce_core/juce_core.h>
#include <vector>

namespace FMSynthPresets
{

/**
 * Factory Presets for FM Synth
 * 20 presets total: Init, E.Piano (5), Bells (5), Bass (4), Lead (5)
 */
inline std::vector<juce::String> getFactoryPresets()
{
    std::vector<juce::String> presets;

    // 1. Init - Basic starting point
    presets.push_back(R"(
<AudioForgePreset name="Init" author="AudioForge" category="Init" description="Basic FM initialization">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    // 2-6. E.Piano variations
    presets.push_back(R"(
<AudioForgePreset name="E.Piano Classic" author="AudioForge" category="E.Piano" description="Classic electric piano">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="E.Piano Bright" author="AudioForge" category="E.Piano" description="Bright electric piano">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="E.Piano Soft" author="AudioForge" category="E.Piano" description="Soft electric piano">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="E.Piano Hard" author="AudioForge" category="E.Piano" description="Hard electric piano">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="E.Piano DX" author="AudioForge" category="E.Piano" description="DX-style electric piano">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    // 7-11. Bells variations
    presets.push_back(R"(
<AudioForgePreset name="Bell Bright" author="AudioForge" category="Bells" description="Bright bell sound">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bell Soft" author="AudioForge" category="Bells" description="Soft bell sound">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bell Metallic" author="AudioForge" category="Bells" description="Metallic bell">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bell Tubular" author="AudioForge" category="Bells" description="Tubular bell">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bell Glockenspiel" author="AudioForge" category="Bells" description="Glockenspiel">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    // 12-15. Bass variations
    presets.push_back(R"(
<AudioForgePreset name="Bass Solid" author="AudioForge" category="Bass" description="Solid FM bass">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bass Pluck" author="AudioForge" category="Bass" description="Plucky FM bass">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bass Deep" author="AudioForge" category="Bass" description="Deep FM bass">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Bass Wobble" author="AudioForge" category="Bass" description="Wobble FM bass">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    // 16-20. Lead variations
    presets.push_back(R"(
<AudioForgePreset name="Lead Bright" author="AudioForge" category="Lead" description="Bright lead">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Lead Soft" author="AudioForge" category="Lead" description="Soft lead">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Lead Aggressive" author="AudioForge" category="Lead" description="Aggressive lead">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Lead Sync" author="AudioForge" category="Lead" description="Sync lead">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    presets.push_back(R"(
<AudioForgePreset name="Lead Smooth" author="AudioForge" category="Lead" description="Smooth lead">
  <ProcessorState></ProcessorState>
</AudioForgePreset>
)");

    return presets;
}

} // namespace FMSynthPresets
